INSERT INTO cases (id,source_case_id,case_name,partners,ip_name,ip_licensor,ip_description,brand_name,brand_industry,brand_description,cooperation_date,cooperation_type,cooperation_form,cooperation_content,product_content,merchandising,activity_play,offline_activity,highlights,reference_value,official_url,tags,ip_type,ip_intro,brand_intro,extra_json,created_at,updated_at) VALUES ('case_excel_1','1','东方墨兰×一人之下','东方墨兰×一人之下','一人之下','阅文','《一人之下》是阅文旗下具有代表性的国漫IP，以现代都市异人与中国传统文化元素结合为特色，拥有大量年轻粉丝群体。','东方墨兰','茶饮','东方墨兰是新中式茶饮品牌，强调东方美学和年轻消费体验。','2026-07-30','IP主题茶饮联名','IP主题茶饮联名','推出“一人之下”主题限定饮品，将张楚岚、冯宝宝等角色视觉元素融入饮品包装与宣传物料','推出“一人之下”主题限定饮品，将张楚岚、冯宝宝等角色视觉元素融入饮品包装与宣传物料','五人角色专属联名杯、限定杯提、氛围感杯套、专属封口贴纸，椰子香牌、拍立得盲袋、杜邦环保袋、反光角色徽章、主题店限定镭射票，多款联名纸袋与保温袋','购买指定联名饮品获得IP限定物料，通过茶饮消费场景触达粉丝用户','东方墨兰门店主题陈列；商圈快闪装置打卡','通过“东方茶饮×东方国漫”的调性匹配，将IP文化元素自然融入消费场景，提升联名内容的契合度。','','https://www.xiaohongshu.com/discovery/item/6a63239f000000001d00dd99?source=webshare&xhsshare=pc_web&xsec_token=ABvR4b5gEr2htul6ZyplWlKY-7buKIcJFofOr5ShP75M8=&xsec_source=pc_share','国漫,茶饮','国漫','《一人之下》是阅文旗下具有代表性的国漫IP，以现代都市异人与中国传统文化元素结合为特色，拥有大量年轻粉丝群体。','东方墨兰是新中式茶饮品牌，强调东方美学和年轻消费体验。','{"excel_sheet":"01_联名案例","excel_case_id":"1","cover_image":"","images":""}','2026-08-11T00:00:00.000Z','2026-08-11T00:00:00.000Z');
